import itertools
from random import shuffle

def task_func(numbers=list(range(1, 3))):
    def sum_of_absolute_differences(permutation):
        return sum(abs(permutation[i] - permutation[i + 1]) for i in range(len(permutation) - 1))

    permutations = list(itertools.permutations(numbers))
    total_sum = 0

    for perm in permutations:
        # Convert tuple to list for shuffling
        perm_list = list(perm)
        shuffle(perm_list)
        total_sum += sum_of_absolute_differences(perm_list)

    return total_sum / len(permutations) if permutations else 0.0
