        data = json.load(file)

    for required_field in INPUT_JSON["required"]:
        if required_field not in data:
            raise ValueError(f"Missing required field: {required_field}")

    for field, field_type in INPUT_JSON["properties"].items():
        if field in data and not isinstance(data[field], field_type["type"]):
            raise ValueError(f"Incorrect type for field {field}: expected {field_type['type'].__name__}, got {type(data[field]).__name__}")

    if attribute not in data:
        raise ValueError(f"The attribute {attribute} is not present in the JSON object.")

    if attribute == "email" and not re.match(EMAIL_REGEX, data["email"]):
        raise ValueError(f"Invalid email format: {data['email']}")

    return data[attribute]
