    if fruits is None:
        fruits = ['Apple', 'Banana', 'Cherry']
    if days is None:
        days = [datetime(2024, 1, 1) + timedelta(n) for n in range(100)]

    if seed is not None:
        np.random.seed(seed)

    sales_data = []
    for fruit, day in itertools.product(fruits, days):
        sales = np.random.randint(sales_lower_bound, sales_upper_bound)
        sales_data.append({'Fruit': fruit, 'Day': day, 'Sales': sales})

    updated_df = pd.DataFrame(sales_data)
    plot = sns.boxplot(data=updated_df, x='Fruit', y='Sales')

    return updated_df, plot
