    try:
        task_func(["iPhone", "iPad"], sales_lower="10", sales_upper=20)
        assert False
    except TypeError as e:
        assert str(e) == "sales_lower and sales_upper must be numeric"

def test_6():
    report = task_func(["iPhone", "iPad", "Macbook"], n_samples=1, sales_lower=100, sales_upper=150, profit_margin_min=0.2, profit_margin_max=0.4, random_seed=42)
