def task_func(df, groups=['A', 'B', 'C', 'D', 'E']):
    if not isinstance(df, pd.DataFrame) or not {'group', 'date', 'value'}.issubset(df.columns):
        raise ValueError("If 'df' is not a DataFrame or lacks required columns.")

    df['date_ordinal'] = df['date'].map(lambda x: x.toordinal())

    fig, ax = plt.subplots()
    colors = cycle(plt.cm.tab10.colors)

    for group in groups:
        group_data = df[df['group'] == group]
        if not group_data.empty:
            ax.scatter(group_data['date_ordinal'], group_data['value'], label=group, color=next(colors))

    ax.set_title('Scatterplot of Values for Each Group Over Time')
    ax.set_xlabel('Date (ordinal)')
    ax.set_ylabel('Value')
    ax.legend()

    return ax
