import requests
from bs4 import BeautifulSoup
import pandas as pd

def task_func(url='http://example.com'):
    try:
        response = requests.get(url)
        response.raise_for_status()
    except requests.ConnectionError:
        raise ConnectionError("Failed to connect to the URL.")
    except requests.HTTPError:
        raise requests.HTTPError("HTTP request to the URL failed.")

    soup = BeautifulSoup(response.content, 'html.parser')
    table = soup.find('table')

    if not table:
        raise ValueError("No table data found on the page.")

    headers = []
    header_row = table.find('tr')
    if header_row:
        headers = [th.get_text(strip=True) for th in header_row.find_all(['th', 'td'])]

    rows = []
    for tr in table.find_all('tr')[1:]:
        row = [td.get_text(strip=True) for td in tr.find_all('td')]
        if row:
            rows.append(row)

    if not rows:
        raise ValueError("No table data found on the page.")

    df = pd.DataFrame(rows, columns=headers if headers else None)
    return df
[TESTS]
def test_1():
    df = task_func('https://en.wikipedia.org/wiki/List_of_countries_by_GDP_(nominal)')
    assert not df.empty
    assert 'Country/Territory' in df.columns or df.columns[0] == 0

def test_2():
    df = task_func('https://en.wikipedia.org/wiki/List_of_countries_by_GDP_(nominal)')
    assert len(df.columns) > 1

