    try:
        task_func('https://httpbin.org/status/404')
    except requests.HTTPError:
        pass
    else:
        assert False, "HTTPError not raised for 404 status."

def test_5():
    try:
        task_func('https://en.wikipedia.org/wiki/ISO_8601')
    except ValueError:
        pass
    else:
        assert False, "ValueError not raised for page without tables."

def test_6():
    df = task_func('https://en.wikipedia.org/wiki/List_of_countries_by_GDP_(nominal)')
    assert len(df) > 0

def test_7():
    df = task_func('https://en.wikipedia.org/wiki/List_of_countries_by_GDP_(nominal)')
    assert df.iloc[0].str.len().sum() > 0, "DataFrame contains empty strings or no data."
