import pandas as pd
import numpy as np
import folium

def task_func(dic={'Lon': (-180, 180), 'Lat': (-90, 90)}, cities=['New York', 'London', 'Beijing', 'Tokyo', 'Sydney']):
    if 'Lon' not in dic or 'Lat' not in dic:
        raise ValueError("Dictionary must contain 'Lon' and 'Lat' keys.")
    if not isinstance(dic['Lon'], tuple) or not isinstance(dic['Lat'], tuple):
        raise ValueError("'Lon' and 'Lat' values must be tuples.")

    lon_min, lon_max = dic['Lon']
    lat_min, lat_max = dic['Lat']

    longitudes = np.random.uniform(lon_min, lon_max, len(cities))
    latitudes = np.random.uniform(lat_min, lat_max, len(cities))

    city_data = pd.DataFrame({
        'City': cities,
        'Longitude': longitudes,
        'Latitude': latitudes
    })

    map_center = [city_data['Latitude'].mean(), city_data['Longitude'].mean()]
    map_obj = folium.Map(location=map_center, zoom_start=2)

    for _, row in city_data.iterrows():
        folium.Marker(
            location=[row['Latitude'], row['Longitude']],
            popup=row['City']
        ).add_to(map_obj)

    return map_obj, city_data
[TESTS]
def test_1():
    dic = {'Lon': (-180, 180), 'Lat': (-90, 90)}
    map_obj, city_data = task_func(dic)
    assert isinstance(map_obj, folium.Map)
    assert isinstance(city_data, pd.DataFrame)
    assert len(city_data) == 5

def test_2():
    dic = {'Lon': (-180, 180), 'Lat': (-90, 90)}
    map_obj, city_data = task_func(dic, ['City1', 'City2'])
    assert len(city_data) == 2

