    # Create a map centered at the first location
    center = (dic[list(dic.keys())[0]]['Lat'], dic[list(dic.keys())[0]]['Lon'])
    m = folium.Map(location=center, zoom_start=10)

    # Add markers for each location
    for name, coords in dic.items():
        folium.Marker([coords['Lat'], coords['Lon']], popup=name).add_to(m)

    # Calculate distances between each pair of locations
    distances = {}
    places = list(dic.keys())
    for i in range(len(places)):
        for j in range(i + 1, len(places)):
            place1 = places[i]
            place2 = places[j]
            coord1 = (dic[place1]['Lat'], dic[place1]['Lon'])
            coord2 = (dic[place2]['Lat'], dic[place2]['Lon'])
            distance = geodesic(coord1, coord2).kilometers
            distances[f"{place1}, {place2}"] = distance

    return m, distances

def test_1():
    result = task_func({'Place1': {'Lat': 0, 'Lon': 0}, 'Place2': {'Lat': 0, 'Lon': 1}})
    assert isinstance(result, tuple) and len(result) == 2
    assert isinstance(result[0], folium.folium.Map) and isinstance(result[1], dict)

def test_2():
