import re
import json
from collections import Counter

def task_func(json_str, top_n=10):
    try:
        data = json.loads(json_str)
    except json.JSONDecodeError:
        return {}

    url_pattern = re.compile(r'https?://[^\s"]+')
    urls = url_pattern.findall(str(data))

    url_count = Counter(urls)
    return dict(url_count.most_common(top_n))

[TESTS]
def test_1():
    assert task_func('{"name": "John", "website": "https://www.example.com"}') == {'https://www.example.com': 1}

def test_2():
    assert task_func('{"urls": ["http://example.com", "https://example.com", "http://example.com"]}') == {'http://example.com': 2, 'https://example.com': 1}

def test_3():
    assert task_func('{"name": "Alice", "profile": {"website": "https://alice.example.com"}}') == {'https://alice.example.com': 1}

def test_4():
    assert task_func('{"links": ["https://a.com", "https://b.com", "https://a.com", "https://c.com", "https://b.com"]}') == {'https://a.com': 2, 'https://b.com': 2, 'https://c.com': 1}

def test_5():
    assert task_func('{"no_urls_here": "just text"}') == {}

def test_6():
