import http.server
import json

SUCCESS_RESPONSE = {
    'status': 'success',
    'message': 'Data received successfully.'
}
ERROR_CONTENT_TYPE_RESPONSE = {
    'status': 'error',
    'message': 'Content-Type header is not application/json'
}
ERROR_NO_DATA_KEY_RESPONSE = {
    'status': 'error',
    'message': 'No data key in request'
}
ERROR_INVALID_JSON_RESPONSE = {
    'status': 'error',
    'message': 'Invalid JSON'
}

def task_func():
    class RequestHandler(http.server.BaseHTTPRequestHandler):
        def do_POST(self):
            content_type, _ = self.headers.get('content-type', '').split(';', 1)[0]
            if content_type != 'application/json':
                self.send_error(400, message=json.dumps(ERROR_CONTENT_TYPE_RESPONSE))
                return

            try:
                length = int(self.headers.get('content-length', 0))
                data = json.loads(self.rfile.read(length).decode('utf-8'))
            except (ValueError, TypeError):
                self.send_error(400, message=json.dumps(ERROR_INVALID_JSON_RESPONSE))
                return

            if 'data' not in data:
                self.send_error(400, message=json.dumps(ERROR_NO_DATA_KEY_RESPONSE))
                return

            self.send_response(200)
            self.send_header('content-type', 'application/json')
            self.end_headers()
            self.wfile.write(json.dumps(SUCCESS_RESPONSE).encode('utf-8'))

    return RequestHandler
