import re
import os
from collections import Counter

def task_func(folder_path: str) -> dict:
    ip_pattern = re.compile(r'\b(?:\d{1,3}\.){3}\d{1,3}\b')
    ip_counter = Counter()

    for root, _, files in os.walk(folder_path):
        for file in files:
            if file.endswith('.log'):
                file_path = os.path.join(root, file)
                with open(file_path, 'r') as f:
                    for line in f:
                        ips = ip_pattern.findall(line)
                        ip_counter.update(ips)

    # Filter out invalid IP addresses (those with numbers > 255)
    valid_ip_counter = {ip: count for ip, count in ip_counter.items() if all(0 <= int(part) <= 255 for part in ip.split('.'))}

