import re
import numpy as np
from collections import Counter
from sklearn.mixture import GaussianMixture

def task_func(text, num_gaussians=1, seed=42):
    if num_gaussians <= 0:
        raise ValueError("num_gaussians must be greater than 0")

    # Extract text outside square brackets
    cleaned_text = re.sub(r'\[.*?\]', '', text)

    # Tokenize and count word frequencies
    words = re.findall(r'\b\w+\b', cleaned_text)
    freqs = Counter(words)

    if num_gaussians > len(freqs):
        raise Exception("num_gaussians must be less than or equal to the number of unique words")

    # Prepare data for Gaussian Mixture Model
    freq_array = np.array(list(freqs.values())).reshape(-1, 1)

    # Fit Gaussian Mixture Model
    gmm = GaussianMixture(n_components=num_gaussians, random_state=seed)
    gmm.fit(freq_array)

    # Extract means and variances
    means = gmm.means_.flatten()
    variances = gmm.covariances_.flatten()

    return freqs, means, variances
[TESTS]
import numpy as np

def test_1():
    freqs, means, variances = task_func("Josie Smith [3996 COLLEGE AVENUE, SOMETOWN, MD 21003]Mugsy Dog Smith [2560 OAK ST, GLENMEADE, WI 14098]")
    assert freqs == {'Josie': 1, 'Smith': 2, 'Mugsy': 1, 'Dog': 1}

def test_2():
    freqs, means, variances = task_func("Alice Bob [123 Main St] Charlie Alice", num_gaussians=2)
    assert freqs == {'Alice': 2, 'Bob': 1, 'Charlie': 1}

def test_3():
    try:
        task_func("Alice Bob [123 Main St] Charlie Alice", num_gaussians=0)
    except ValueError as e:
        assert str(e) == "num_gaussians must be greater than 0"

def test_4():
    try:
        task_func("Alice Bob [123 Main St] Charlie Alice", num_gaussians=5)
    except Exception as e:
        assert str(e) == "num_gaussians must be less than or equal to the number of unique words"

def test_5():
