        pattern = f'% {random_string}%'
        patterns.append(pattern)
        for char in pattern:
            if char in char_count:
                char_count[char] += 1
            else:
                char_count[char] = 1

    fig, ax = plt.subplots()
    ax.bar(char_count.keys(), char_count.values())

    return patterns, ax, char_count

