import pandas as pd
from collections import Counter
import matplotlib.pyplot as plt

def task_func(text_dict, word_keys, top_k=2):
    if top_k < 0:
        raise ValueError("top_k must be a non-negative integer.")

    # Calculate frequencies for the given word keys
    word_frequencies = {word: text_dict.get(word, 0) for word in word_keys}

    # Get the top_k most common words from the text_dict
    most_common = text_dict.most_common()
    top_words = dict(most_common[:top_k])

    # Combine the word frequencies and top words, then sort by frequency
    combined_frequencies = {**word_frequencies, **top_words}
    sorted_frequencies = dict(sorted(combined_frequencies.items(), key=lambda item: item[1], reverse=True))

    # Create a bar chart
    fig, ax = plt.subplots()
    ax.bar(sorted_frequencies.keys(), sorted_frequencies.values())

    # Return the Axes object and the top_k frequencies
    return ax, top_words

[TESTS]
def test_1():
    text_dict = Counter(['the', 'be', 'to', 'the', 'that', 'and', 'a', 'in', 'the', 'that', 'have', 'I'])
    word_keys = ['the', 'and', 'I']
    ax, frequencies = task_func(text_dict, word_keys, 3)
    assert frequencies == {'the': 3, 'that': 2, 'be': 1}

def test_2():
    text_dict = Counter(['hello', 'world', 'hello'])
    word_keys = ['hello', 'world', 'python']
    ax, frequencies = task_func(text_dict, word_keys, 2)
    assert frequencies == {'hello': 2, 'world': 1}

def test_3():
    text_dict = Counter(['a', 'b', 'c', 'a', 'b', 'a'])
    word_keys = ['a', 'b', 'c']
    ax, frequencies = task_func(text_dict, word_keys, 1)
    assert frequencies == {'a': 3}

def test_4():
    text_dict = Counter(['one', 'two', 'three'])
    word_keys = ['four', 'five', 'six']
    ax, frequencies = task_func(text_dict, word_keys, 3)
    assert frequencies == {}

def test_5():
    text_dict = Counter(['x', 'y', 'x', 'y', 'x'])
    word_keys = ['x', 'y']
    ax, frequencies = task_func(text_dict, word_keys, 0)
    assert frequencies == {}

def test_6():
    text_dict = Counter(['x', 'y', 'x', 'y', 'x'])
    word_keys = ['x', 'y']
    try:
        ax, frequencies = task_func(text_dict, word_keys, -1)
