import json
from glob import glob
import os

def task_func(directory, string):
    def search_json_files(dir_path):
        json_files = glob(os.path.join(dir_path, '*.json'))
        for json_file in json_files:
            try:
                with open(json_file, 'r') as file:
                    data = json.load(file)
                    if string in data.values():
                        yield json_file
            except (json.JSONDecodeError, FileNotFoundError):
                continue
        for subdir in glob(os.path.join(dir_path, '*')):
            if os.path.isdir(subdir):
                yield from search_json_files(subdir)

    return list(search_json_files(directory))
