    try:
        df = pd.read_excel(file_path)
    except Exception as e:
        raise ValueError(f"Error reading the Excel file: {e}")

    if column_name not in df.columns:
        raise ValueError(f"The specified column '{column_name}' is not found in the Excel file.")

    data = df[column_name].dropna()
    if data.empty:
        raise ValueError(f"The specified column '{column_name}' contains no valid data.")

    mean_value = np.mean(data)
    median_value = np.median(data)
    std_dev_value = np.std(data, ddof=0)  # Population standard deviation

    return {'mean': mean_value, 'median': median_value, 'std_dev': std_dev_value}

