import json
import re
import pandas as pd

def task_func(json_str):
    if not json_str.strip():
        return pd.DataFrame()

    try:
        data = json.loads(json_str)
    except json.JSONDecodeError:
        return pd.DataFrame()

    def double_value(value):
        if isinstance(value, (int, float)):
            return value * 2
        elif isinstance(value, list):
            return [double_value(item) for item in value]
        elif isinstance(value, str):
            match = re.match(r'^-?\d+(\.\d+)?$', value)
            if match:
                return float(value) * 2
        return value

    normalized_data = {key: double_value(value) for key, value in data.items()}

    return pd.DataFrame(normalized_data)

[TESTS]
def test_1():
    json_str = '{"a": [1, 2, 3], "b": 4.9, "c": "5"}'
    df = task_func(json_str)
    expected_df = pd.DataFrame({'a': [2, 4, 6], 'b': [9.8], 'c': [10.0]})
    assert df.equals(expected_df)

def test_2():
    json_str = '{"x": "10", "y": 3, "z": [2.5, 4]}'
    df = task_func(json_str)
    expected_df = pd.DataFrame({'x': [20.0], 'y': [6], 'z': [[5.0, 8]]})
    assert df.equals(expected_df)

def test_3():
