    df = task_func(json_str)
    expected_df = pd.DataFrame({'empty': [[]]})
    assert df.equals(expected_df)

def test_5():
    json_str = '{"invalid": "abc", "number": 5}'
    df = task_func(json_str)
    expected_df = pd.DataFrame({'invalid': ['abc'], 'number': [10.0]})
