from enum import Enum

class Color(Enum):
    RED = 1
    GREEN = 2
    BLUE = 3

def task_func(my_obj):
    class EnumEncoder(json.JSONEncoder):
        def default(self, obj):
            if isinstance(obj, Enum):
                return obj.name
            return super().default(obj)
    return json.dumps(my_obj, cls=EnumEncoder)

[TESTS]
def test_1():
    assert task_func({'color': Color.RED}) == '{"color": "RED"}'

def test_2():
    assert task_func({'name': 'Alice', 'age': 30}) == '{"name": "Alice", "age": 30}'

def test_3():
    assert task_func({'colors': [Color.RED, Color.BLUE]}) == '{"colors": ["RED", "BLUE"]}'

def test_4():
    assert task_func({'nested': {'color': Color.GREEN}}) == '{"nested": {"color": "GREEN"}}'

def test_5():
    assert task_func({}) == '{}'

def test_6():
    assert task_func({'number': 42}) == '{"number": 42}'

def test_7():
    assert task_func({'boolean': True, 'none': None}) == '{"boolean": true, "none": null}'

