import numpy as np
import matplotlib.pyplot as plt
import itertools

def task_func(n_walks, n_steps, seed=None):
    if n_walks <= 0:
        raise ValueError("n_walks must be greater than 0")
    if n_steps <= 0:
        raise ValueError("n_steps must be greater than 0")

    if seed is not None:
        np.random.seed(seed)

    colors = itertools.cycle(['b', 'g', 'r', 'c', 'm', 'y', 'k'])
    walks = np.random.randint(0, 2, (n_walks, n_steps)) * 2 - 1
    walks = walks.cumsum(axis=1)

    fig, ax = plt.subplots()
    for walk, color in zip(walks, colors):
        ax.plot(walk, color=color)

    return ax

[TESTS]
import numpy as np
import matplotlib.pyplot as plt

def test_1():
    ax = task_func(5, 100, seed=42)
    assert type(ax) == plt.Axes

def test_2():
    ax = task_func(5, 100, seed=42)
    xticklabels = [tick.get_text() for tick in ax.get_xticklabels()]
    assert xticklabels == ['−20', '0', '20', '40', '60', '80', '100', '120']

def test_3():
    ax = task_func(1, 10, seed=42)
    lines = ax.get_lines()
    assert len(lines) == 1

def test_4():
    ax = task_func(7, 10, seed=42)
    lines = ax.get_lines()
    colors = [line.get_color() for line in lines]
    expected_colors = ['b', 'g', 'r', 'c', 'm', 'y', 'k']
    assert colors == expected_colors

def test_5():
    try:
        task_func(0, 10)
    except ValueError as e:
        assert str(e) == "n_walks must be greater than 0"

def test_6():
    try:
        task_func(10, 0)
    except ValueError as e:
        assert str(e) == "n_steps must be greater than 0"

def test_7():
    ax = task_func(5, 100, seed=42)
    yticklabels = [tick.get_text() for tick in ax.get_yticklabels()]
    assert yticklabels == ['−15', '−10', '−5', '0', '5', '10', '15']

