import pandas as pd
from datetime import datetime
import matplotlib.pyplot as plt

def task_func(data, date_format, country, country_codes=None):
    if not isinstance(data, pd.DataFrame):
        raise ValueError("The 'data' should be a DataFrame.")
    if not isinstance(date_format, str):
        raise ValueError("The 'date_format' should be a string.")
    if country_codes is None or not isinstance(country_codes, dict):
        raise ValueError("The 'country_codes' should be a dictionary.")
    if country not in country_codes:
        raise ValueError("The 'country' should be in 'country_codes'.")

    # Convert dates to datetime format
    data['dates'] = pd.to_datetime(data['dates'], format=date_format)

    # Plot histogram
    ax = data['dates'].hist(bins=10)
    ax.set_title('Date Distribution')
    ax.set_ylabel('Frequency')

    return ax

[TESTS]
def test_1():
    data = pd.DataFrame({'dates': ['01/01/2000', '01/02/2000', '02/03/2000', '04/05/2000', '06/07/2000']})
    ax = task_func(data, '%d/%m/%Y', 'Russia', {'Russia': 'RU'})
    assert ax.get_title() == 'Date Distribution'

def test_2():
    try:
        task_func([1, 2, 3], '%d/%m/%Y', 'Russia', {'Russia': 'RU'})
    except ValueError as e:
        assert str(e) == "The 'data' should be a DataFrame."

def test_3():
    try:
        task_func(pd.DataFrame({'dates': ['01/01/2000']}), 123, 'Russia', {'Russia': 'RU'})
    except ValueError as e:
        assert str(e) == "The 'date_format' should be a string."

def test_4():
    try:
        task_func(pd.DataFrame({'dates': ['01/01/2000']}), '%d/%m/%Y', 'Russia')
    except ValueError as e:
        assert str(e) == "The 'country_codes' should be a dictionary."

def test_5():
    try:
        task_func(pd.DataFrame({'dates': ['01/01/2000']}), '%d/%m/%Y', 'USA', {'Russia': 'RU'})
    except ValueError as e:
        assert str(e) == "The 'country' should be in 'country_codes'."

def test_6():
    data = pd.DataFrame({'dates': ['01/01/2000', '01/02/2000', '02/03/2000', '04/05/2000', '06/07/2000']})
    ax = task_func(data, '%d/%m/%Y', 'Russia', {'Russia': 'RU'})
