    df = task_func(['one'], seed=2)
    assert df.iloc[0]['Modified String'] == 'one'

def test_4():
    df = task_func(['red, blue, green'], seed=3)
    assert df.iloc[0]['Modified String'] == 'green, random_string, red'

def test_5():
    df = task_func(['x, y, z'], seed=4)
