def test_6():
    df = task_func(['a, b, c, d'], seed=5)
    assert df.iloc[0]['Modified String'] == 'c, d, a, b'

def test_7():
    df = task_func(['hello, world'], seed=6)
    assert df.iloc[0]['Modified String'] == 'world, hello'

