import xmltodict
import json

def task_func(s, save_json=False, json_file_path=None):
    if not s.strip():
        raise ValueError("The input XML string is empty or contains only whitespace.")

    try:
        result = xmltodict.parse(s)
    except Exception as e:
        raise ValueError(f"Error parsing XML: {str(e)}")

    if save_json and json_file_path:
        with open(json_file_path, 'w') as json_file:
            json.dump(result, json_file, indent=4)

    return result
[TESTS]
def test_1():
    result = task_func('<person><name>John</name><age>30</age></person>')
    assert result['person']['name'] == 'John'
    assert result['person']['age'] == '30'

def test_2():
    result = task_func('<school><class><student>Emma</student></class></school>')
    assert result['school']['class']['student'] == 'Emma'

def test_3():
    try:
        task_func('<data><item>1</item><item>2</item></data>', save_json=True, json_file_path='data.json')
        with open('data.json', 'r') as json_file:
            result = json.load(json_file)
        assert result['data']['item'] == ['1', '2']
    finally:
        import os
        os.remove('data.json')

def test_4():
    try:
        task_func('<invalid>')
    except ValueError as e:
        assert str(e) == "Error parsing XML: No closing tag found for '$document'."
    else:
        assert False, "Expected ValueError"

def test_5():
    try:
        task_func('   ')
    except ValueError as e:
        assert str(e) == "The input XML string is empty or contains only whitespace."
    else:
        assert False, "Expected ValueError"

def test_6():
    result = task_func('<root><tag>Value</tag></root>')
    assert result['root']['tag'] == 'Value'

def test_7():
    result = task_func('<root><tag1>Value1</tag1><tag2>Value2</tag2></root>')
    assert result['root']['tag1'] == 'Value1'
    assert result['root']['tag2'] == 'Value2'

