import pandas as pd
import numpy as np
import matplotlib.pyplot as plt

def task_func(column, data):
    df = pd.DataFrame(data, columns=['Product', 'Quantity', 'Total Sales'])

    if (df['Quantity'] < 0).any() or (df['Total Sales'] < 0).any():
        raise ValueError("Quantity sold or total sales cannot be negative.")

    column_values = df[column]
    stats = {
        'sum': column_values.sum(),
        'mean': column_values.mean(),
        'min': column_values.min(),
        'max': column_values.max()
    }

    fig, ax = plt.subplots()
    ax.bar(df['Product'], column_values)
    ax.set_title(f'Bar Chart of {column}')
    ax.set_xlabel('Product')

    return stats, ax

[TESTS]
def test_1():
    data = [['Product A', 100, 10000], ['Product B', 150, 15000], ['Product C', 200, 20000]]
    stats, plot = task_func('Total Sales', data)
    assert stats == {'sum': 45000, 'mean': 15000.0, 'min': 10000, 'max': 20000}
    assert plot.get_title() == 'Bar Chart of Total Sales'
    assert list(plot.get_xlabel()) == list('Product')

