    data = [['Product X', 50, 5000], ['Product Y', 75, 11250]]
    stats, plot = task_func('Quantity', data)
    assert stats == {'sum': 125, 'mean': 62.5, 'min': 50, 'max': 75}
    assert plot.get_title() == 'Bar Chart of Quantity'

