import collections
import matplotlib.pyplot as plt

def task_func(data):
    if not data:
        return {}, None

    total_sales = collections.defaultdict(int)
    fruit_colors = {'apple': 'red', 'banana': 'yellow', 'cherry': 'green', 'orange': 'orange', 'grape': 'purple'}

    for entry in data:
        for fruit, quantity in entry.items():
            if quantity < 0:
                raise ValueError("Sales quantity must not be negative.")
            total_sales[fruit] += quantity

    fruits = list(total_sales.keys())
    sales = list(total_sales.values())
    colors = [fruit_colors.get(fruit, 'gray') for fruit in fruits]

    fig, ax = plt.subplots()
    ax.bar(fruits, sales, color=colors)
    plt.xlabel('Fruit')
    plt.ylabel('Total Sales')
    plt.title('Total Sales by Fruit')

    return dict(total_sales), ax.containers[0]
