from collections import defaultdict
import numpy as np
import matplotlib.pyplot as plt

def task_func(data):
    if not data:
        raise ValueError("The input data is empty.")
    if not isinstance(data, list) or not all(isinstance(item, dict) for item in data):
        raise TypeError("The input is not a list of dictionaries.")
    for item in data:
        for value in item.values():
            if not isinstance(value, (int, float)):
                raise TypeError("All values in the dictionaries must be numeric.")

    stats = defaultdict(list)
    for item in data:
        for key, value in item.items():
            stats[key].append(value)

    stats_dict = {}
    axes_list = []
    for key, values in stats.items():
        mean = np.mean(values)
        std = np.std(values)
        stats_dict[key] = {'mean': mean, 'std': std}

        fig, ax = plt.subplots()
        ax.bar(['Mean', 'Std'], [mean, std], yerr=[0, std], capsize=5)
        ax.set_title(f'Statistics of {key}')
        ax.set_ylabel('Value')
        axes_list.append(ax)

    return stats_dict, axes_list
