        defaults = [p.default for p in params.values() if p.default is not inspect.Parameter.empty]
        annotations = {k: v for k, v in sig.annotations.items()}
        is_lambda = f.__name__ == "<lambda>"

        functions_info.append({
            'Function Name': name,
            'Number of Arguments': num_args,
            'Defaults': defaults,
            'Annotations': annotations,
            'Is Lambda': is_lambda
        })

    df = pd.DataFrame(functions_info)
    try:
        df.to_csv(file_path, index=False)
    except Exception as e:
        raise IOError(f"Error writing to file: {e}")

