import re
import nltk
import pandas as pd
from sklearn.feature_extraction.text import CountVectorizer

# Make sure to download NLTK stopwords
nltk.download('stopwords')
# Define a regex pattern for matching all non-alphanumeric characters
ALPHANUMERIC = re.compile('[\W_]+')
# Load NLTK's list of English stop words
STOPWORDS = nltk.corpus.stopwords.words('english')

def task_func(texts):
    # Preprocess the texts
    processed_texts = [' '.join(
        ALPHANUMERIC.sub(' ', text).lower().split()
    ) for text in texts]

    # Initialize the CountVectorizer with the stopwords
    vectorizer = CountVectorizer(stop_words=STOPWORDS)

    # Fit and transform the processed texts to create the document-term matrix
    dtm = vectorizer.fit_transform(processed_texts)

    # Convert the document-term matrix to a DataFrame
    df_dtm = pd.DataFrame(dtm.toarray(), columns=vectorizer.get_feature_names_out())

    return df_dtm

[TESTS]
def test_1():
    texts = ["Hello, world!", "Machine learning is great.", "Python is my favorite programming language."]
    df = task_func(texts)
    assert set(df.columns) == {'hello', 'world', 'machine', 'learning', 'great', 'python', 'favorite', 'programming', 'language'}

