import pandas as pd
import numpy as np

def task_func(data, cols):
    df = pd.DataFrame(data, columns=cols)
    correlation_matrix = df.corr()
    return correlation_matrix

[TESTS]
def test_1():
    correlation_matrix = task_func([[5.1, 3.5, 1.4], [4.9, 3.0, 1.4], [4.7, 3.2, 1.3]], ['x', 'y', 'z'])
    expected = pd.DataFrame({
        'x': [1.000000, 0.596040, 0.866025],
        'y': [0.596040, 1.000000, 0.114708],
        'z': [0.866025, 0.114708, 1.000000]
    }, index=['x', 'y', 'z'])
    pd.testing.assert_frame_equal(correlation_matrix.round(6), expected)

def test_2():
    correlation_matrix = task_func([[1, 2, 3], [4, 5, 6], [7, 8, 9]], ['a', 'b', 'c'])
    expected = pd.DataFrame({
        'a': [1.0, 1.0, 1.0],
        'b': [1.0, 1.0, 1.0],
        'c': [1.0, 1.0, 1.0]
    }, index=['a', 'b', 'c'])
    pd.testing.assert_frame_equal(correlation_matrix.round(6), expected)

def test_3():
    correlation_matrix = task_func([[1, 0], [0, 1]], ['u', 'v'])
    expected = pd.DataFrame({
        'u': [1.0, -1.0],
        'v': [-1.0, 1.0]
    }, index=['u', 'v'])
    pd.testing.assert_frame_equal(correlation_matrix.round(6), expected)

def test_4():
    correlation_matrix = task_func([[10, 20], [30, 40], [50, 60]], ['m', 'n'])
    expected = pd.DataFrame({
        'm': [1.0, 1.0],
        'n': [1.0, 1.0]
    }, index=['m', 'n'])
    pd.testing.assert_frame_equal(correlation_matrix.round(6), expected)

def test_5():
    correlation_matrix = task_func([[1], [2], [3]], ['s'])
    expected = pd.DataFrame({
        's': [1.0]
    }, index=['s'])
    pd.testing.assert_frame_equal(correlation_matrix.round(6), expected)

def test_6():
    correlation_matrix = task_func([[0, 0, 0], [0, 0, 0]], ['p', 'q', 'r'])
    expected = pd.DataFrame({
        'p': [np.nan, np.nan, np.nan],
        'q': [np.nan, np.nan, np.nan],
        'r': [np.nan, np.nan, np.nan]
    }, index=['p', 'q', 'r'])
    pd.testing.assert_frame_equal(correlation_matrix.isnull(), expected.isnull())

