import heapq
from scipy import stats
import pandas as pd

def task_func(df, col1, col2, N=10):
    if col1 not in df.columns or col2 not in df.columns:
        raise ValueError("Specified columns are not in the provided DataFrame.")
    if N <= 1:
        raise ValueError("N must be greater than 1.")

    # Calculate the absolute differences
    abs_diff = (df[col1] - df[col2]).abs()

    # Find the N largest absolute differences
    largest_indices = heapq.nlargest(N, range(len(abs_diff)), key=abs_diff.__getitem__)

    # Select the rows with the largest differences
    sample1 = df[col1].iloc[largest_indices]
    sample2 = df[col2].iloc[largest_indices]

    # Perform t-test
    t_stat, p_value = stats.ttest_ind(sample1, sample2)

    return p_value
