import collections
import csv

def task_func(file_name):
    with open(file_name, mode='r', newline='') as file:
        reader = csv.DictReader(file)
        if not reader.fieldnames:
            return {}

        column_counters = {field: collections.Counter() for field in reader.fieldnames}

        for row in reader:
            for field in reader.fieldnames:
                column_counters[field][row[field]] += 1

        common_values = {}
        for field, counter in column_counters.items():
            if counter:
                most_common_values = counter.most_common()
                max_count = most_common_values[0][1]
                most_common_sorted = [value for value, count in most_common_values if count == max_count]
                common_values[field] = sorted(most_common_sorted)[0]
            else:
                common_values[field] = None

        return common_values
