import os
import errno
import shutil

def task_func(filename, dest_dir):
    # Ensure the destination directory exists
    try:
        os.makedirs(dest_dir, exist_ok=True)
    except OSError as e:
        if e.errno != errno.EEXIST:
            raise OSError(f"Destination directory cannot be created: {e}")

    # Copy the file to the destination directory
    dest_file = os.path.join(dest_dir, os.path.basename(filename))
    try:
        shutil.copy2(filename, dest_file)
    except OSError as e:
        raise OSError(f"File cannot be copied: {e}")

    # Clear the contents of the original file
    with open(filename, 'w') as f:
        f.truncate(0)

    # Return the absolute path to the copied file
    return os.path.abspath(dest_file)
