import re
import numpy as np
from collections import Counter
from Levenshtein import ratio

# Constants
ALPHANUMERIC = re.compile('[\W_]+')

def task_func(text1, text2):
    def clean_text(text):
        return ALPHANUMERIC.sub(' ', text).lower()

    def cosine_similarity(text1, text2):
        vec1 = Counter(text1.split())
        vec2 = Counter(text2.split())

        intersection = set(vec1.keys()) & set(vec2.keys())
        numerator = sum([vec1[x] * vec2[x] for x in intersection])

        sum1 = sum([vec1[x] ** 2 for x in vec1.keys()])
        sum2 = sum([vec2[x] ** 2 for x in vec2.keys()])
        denominator = np.sqrt(sum1) * np.sqrt(sum2)

        if not denominator:
            return 0.0
        else:
            return float(numerator) / denominator

    cleaned_text1 = clean_text(text1)
    cleaned_text2 = clean_text(text2)

    cos_sim = cosine_similarity(cleaned_text1, cleaned_text2)
    lev_ratio = ratio(cleaned_text1, cleaned_text2)

    return (cos_sim, lev_ratio)
[TESTS]
