import pandas as pd
import numpy as np

def task_func(fruit_data):
    if not fruit_data:
        return pd.DataFrame(columns=['Total Count', 'Average Count'])

    fruit_dict = {}
    for fruit, count in fruit_data:
        if fruit in fruit_dict:
            fruit_dict[fruit]['total'] += count
            fruit_dict[fruit]['count'] += 1
        else:
            fruit_dict[fruit] = {'total': count, 'count': 1}

    data = {
        'Total Count': [fruit_dict[fruit]['total'] for fruit in fruit_dict],
        'Average Count': [fruit_dict[fruit]['total'] / fruit_dict[fruit]['count'] for fruit in fruit_dict]
    }

    df = pd.DataFrame(data, index=fruit_dict.keys())
    return df
