    max_length = max(len(t) for t in data_list)

    # Unzip the tuples, filling missing values with None
    unzipped = itertools.zip_longest(*data_list, fillvalue=None)

    means = []
    for values in unzipped:
        # Filter out non-numeric values and replace None with 0
        numeric_values = [v if isinstance(v, (int, float)) else 0 for v in values]
        if all(v == 0 for v in numeric_values):
