import re
from datetime import time, datetime

def task_func(logs: list):
    error_times = []
    for log in logs:
        if 'ERROR' in log:
            time_str = log.split()[1]
            error_time = datetime.strptime(time_str, '%H:%M:%S').time()
            error_times.append(error_time)

    if not error_times:
        return ([], None)

    total_seconds = sum(t.hour * 3600 + t.minute * 60 + t.second for t in error_times)
    avg_seconds = total_seconds // len(error_times)
    avg_time = time(avg_seconds // 3600, (avg_seconds % 3600) // 60, avg_seconds % 60)

    return (error_times, avg_time)
