import pandas as pd
import re

# Function to replace acronyms in DataFrame
def task_func(data, mapping):
    def replace_acronyms(text):
        def replacer(match):
            acronym = match.group(0)
            return mapping.get(acronym, acronym)
        # Use regex to find all acronyms in the text
        return re.sub(r'\b(' + '|'.join(re.escape(key) for key in mapping.keys()) + r')\b', replacer, text)

    # Apply the replacement function to all string cells in the DataFrame
    return data.applymap(lambda x: replace_acronyms(x) if isinstance(x, str) else x)

[TESTS]
def test_1():
    data = pd.DataFrame({'text': ['NASA is great', 'I live in the USA']})
    mapping = {'NASA': 'National Aeronautics and Space Administration', 'USA': 'United States of America'}
    result = task_func(data, mapping)
    expected = pd.DataFrame({'text': ['National Aeronautics and Space Administration is great', 'I live in the United States of America']})
