def task_func(
    task_list,
    n_tasks,
    employees=["John Doe", "Jane Smith", "James Brown", "Mary Johnson", "Robert Davis"],
    seed=None,
):
    if n_tasks < 0:
        raise ValueError("n_tasks must be non-negative")

    if seed is not None:
        random.seed(seed)

    selected_tasks = random.sample(task_list, min(n_tasks, len(task_list)))
    assigned_employees = random.choices(employees, k=len(selected_tasks))
    due_date = datetime.now().strftime('%Y-%m-%d')

    sanitized_tasks = [task.replace(' ', '_') for task in selected_tasks]

    df = pd.DataFrame({
        'Task Name': sanitized_tasks,
        'Assigned To': assigned_employees,
        'Due Date': [due_date] * len(selected_tasks)
    })

    return df

