import re
import string
import random

def task_func(text: str, seed=None) -> str:
    if seed is not None:
        random.seed(seed)

    # Remove special characters (punctuation)
    text = re.sub(f"[{re.escape(string.punctuation)}]", "", text)

    # Normalize whitespace
    text = text.replace(' ', '_').replace('\t', '__').replace('\n', '___')

    # Randomize character casing
    randomized_text = ''.join(random.choice([char.upper(), char.lower()]) for char in text)

    return randomized_text

