import os
import shutil

def task_func(path, delimiter="/"):
    if not isinstance(path, str) or not path:
        raise ValueError("The 'path' must be a non-empty string.")

    components = path.split(delimiter)

    for component in components:
        if not component or not os.path.exists(os.path.join(delimiter, component)):
            raise FileNotFoundError(f"The path '{path}' does not exist in the filesystem.")

    disk_usage_list = []
    for component in components:
        full_path = os.path.join(delimiter, component)
        total, used, free = shutil.disk_usage(full_path)
        disk_usage_list.append((component, {'total': total, 'used': used, 'free': free}))

    return disk_usage_list

