import pandas as pd
import json
import os
import math

def task_func(json_data, output_dir=".", file_name="country_population_report.csv"):
    try:
        data = json.loads(json_data)
    except json.JSONDecodeError:
        raise ValueError("The JSON data is malformed.")

    if not data or "Countries" not in data:
        raise ValueError("The JSON data is empty or missing 'Countries' key.")

    countries = data["Countries"]
    if not isinstance(countries, dict):
        raise ValueError("The 'Countries' value should be a dictionary.")

    country_population_list = []
    for country, population in countries.items():
        if not isinstance(country, str):
            raise ValueError("Country names must be strings.")
        if not isinstance(population, (int, float)) or population < 0:
            raise ValueError("Populations must be non-negative numbers.")
        country_population_list.append((country, math.floor(population)))

    df = pd.DataFrame(country_population_list, columns=["Country", "Population"])

    csv_file_path = os.path.join(output_dir, file_name)
    try:
        df.to_csv(csv_file_path, index=False)
    except IOError:
        raise IOError("The file cannot be written to the specified directory.")

    return csv_file_path, df

