import random
import string

def task_func(length: int, predicates: list, seed: int = None):
    if length < 0:
        raise ValueError("The specified length is negative.")

    if seed is not None:
        random.seed(seed)

    predicates = list(set(predicates))
    valid_predicates = {'has_uppercase', 'has_lowercase', 'has_numbers'}
    invalid_predicates = set(predicates) - valid_predicates
    if invalid_predicates:
        raise KeyError(f"Unrecognized predicates: {invalid_predicates}")

    char_pool = string.ascii_letters + string.digits + string.punctuation
    random_string = ''.join(random.choice(char_pool) for _ in range(length))

    characteristics = {
        'has_uppercase': any(c.isupper() for c in random_string),
        'has_lowercase': any(c.islower() for c in random_string),
        'has_numbers': any(c.isdigit() for c in random_string)
    }

    result = {key: characteristics[key] for key in predicates}

    return random_string, result

[TESTS]
