import urllib.request
from lxml import etree
import pandas as pd

def task_func(url):
    try:
        with urllib.request.urlopen(url) as response:
            xml_content = response.read()
    except Exception as e:
        raise ValueError("URL is invalid or the XML file cannot be fetched from the URL.") from e

    try:
        root = etree.fromstring(xml_content)
    except etree.XMLSyntaxError as e:
        raise ValueError("XML file has invalid syntax.") from e

    # Assuming the expected XML structure is <root><item><name>...</name><age>...</age></item>...</root>
    try:
        items = root.findall('.//item')
        data = []
        columns = set()

        for item in items:
            row = {}
            for child in item:
                row[child.tag] = child.text
                columns.add(child.tag)
            data.append(row)

        if not data:
            raise ValueError("XML structure does not match expected format.")

        columns = list(columns)
        df_data = {col: [row.get(col) for row in data] for col in columns}
        df = pd.DataFrame(df_data, columns=columns)
        return df

    except Exception as e:
        raise ValueError("XML structure does not match expected format.") from e
