import pandas as pd
import os
from datetime import datetime
from pandas.errors import EmptyDataError

def task_func(csv_file_path, column_name, date_format="%Y-%m-%d"):
    if not os.path.exists(csv_file_path):
        raise FileNotFoundError(f"The specified CSV file is not found at the given path: {csv_file_path}")

    try:
        df = pd.read_csv(csv_file_path)
    except EmptyDataError:
        return pd.DataFrame(columns=[column_name, 'Value'])

    if column_name not in df.columns:
        raise ValueError(f"The specified column is not present in the CSV file: {column_name}")

    try:
        df[column_name] = pd.to_datetime(df[column_name], format=date_format)
    except Exception as e:
        raise ValueError(f"Error converting date values to datetime objects: {e}")

    current_date = datetime.now().date()
    filtered_df = df[df[column_name].dt.date <= current_date]
    sorted_df = filtered_df.sort_values(by=column_name).reset_index(drop=True)

    return sorted_df[['Date', 'Value']]
