import socket
import select
import queue
from datetime import datetime, timedelta

def task_func(
    server_address="localhost", server_port=12345, buffer_size=1024, run_duration=5
):
    server = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    server.bind((server_address, server_port))
    server.listen(5)
    server.setblocking(0)

    inputs = [server]
    outputs = []
    message_queues = {}

    start_time = datetime.now()

    while (datetime.now() - start_time) < timedelta(seconds=run_duration):
        readable, writable, exceptional = select.select(inputs, outputs, inputs, 1)

        for s in readable:
            if s is server:
                connection, client_address = s.accept()
                connection.setblocking(0)
                inputs.append(connection)
                message_queues[connection] = queue.Queue()
            else:
                data = s.recv(buffer_size)
                if data:
                    current_time = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
                    message_queues[s].put(data + current_time.encode())
                    if s not in outputs:
                        outputs.append(s)
                else:
                    if s in outputs:
                        outputs.remove(s)
                    inputs.remove(s)
                    s.close()
                    del message_queues[s]

        for s in writable:
            try:
                next_msg = message_queues[s].get_nowait()
            except queue.Empty:
                outputs.remove(s)
            else:
                s.send(next_msg)

        for s in exceptional:
            inputs.remove(s)
            if s in outputs:
                outputs.remove(s)
            s.close()
            del message_queues[s]

    server.close()
    return f"Server started on {server_address}:{server_port}. Ran for {run_duration} seconds."

[TESTS]
def test_1():
    assert callable(task_func)

def test_2():
    result = task_func(run_duration=0)
    assert "Ran for 0 seconds." in result

def test_3():
    result = task_func(run_duration=1)
    assert "Ran for 1 seconds." in result

def test_4():
    result = task_func(run_duration=3)
    assert "Ran for 3 seconds." in result

def test_5():
    result = task_func(server_address="127.0.0.1", run_duration=2)
    assert "Server started on 127.0.0.1:12345. Ran for 2 seconds." in result

def test_6():
    result = task_func(server_port=54321, run_duration=2)
    assert "Server started on localhost:54321. Ran for 2 seconds." in result

def test_7():
    result = task_func(buffer_size=2048, run_duration=2)
    assert "Ran for 2 seconds." in result
