import requests
import logging

def task_func(repo_url: str) -> dict:
    try:
        response = requests.get(repo_url)
        response.raise_for_status()  # Raise an HTTPError for bad responses
        repo_info = response.json()

        open_issues_count = repo_info.get('open_issues_count', 0)
        if open_issues_count > 100:
            logging.warning(f"Repository has a high number of open issues: {open_issues_count}")

        return repo_info

    except requests.exceptions.HTTPError as http_err:
        if response.status_code == 403 and 'rate limit exceeded' in response.text.lower():
            raise requests.exceptions.HTTPError("GitHub API rate limit exceeded") from http_err
        else:
            raise http_err
    except requests.exceptions.RequestException as req_err:
        raise req_err

