from datetime import datetime
import pytz
import numpy as np

def task_func(time_strings, timezone):
    if len(time_strings) < 2:
        return 0.0

    tz = pytz.timezone(timezone)
    converted_times = []

    for ts in time_strings:
        dt = datetime.strptime(ts, '%d/%m/%y %H:%M:%S.%f')
        dt = pytz.utc.localize(dt)
        dt = dt.astimezone(tz)
        converted_times.append(dt)

    time_diffs = [(t2 - t1).total_seconds() for t1, t2 in zip(converted_times, converted_times[1:])]

    if not time_diffs:
        return 0.0

    return np.mean(time_diffs)
[TESTS]
def test_1():
    time_strings = ['30/03/09 16:31:32.123', '30/03/09 16:32:33.123', '30/03/09 16:33:34.123']
