from scipy.stats import pearsonr
import numpy as np

def task_func(data):
    if len(data['Score_String']) < 2:
        return np.nan

    scores = list(map(float, data['Score_String']))
    unique_grades = sorted(set(data['Grade']), reverse=True)
    grade_to_value = {grade: i for i, grade in enumerate(unique_grades)}
    grades_encoded = [grade_to_value[grade] for grade in data['Grade']]

    correlation, _ = pearsonr(scores, grades_encoded)
    return correlation

