import re
import urllib.parse
import ssl
import socket
from datetime import datetime

def task_func(myString):
    # Regular expression to find URLs
    url_pattern = re.compile(r'https://[^\s,]+')
    urls = url_pattern.findall(myString)

    result = {}

    for url in urls:
        parsed_url = urllib.parse.urlparse(url)
        domain = parsed_url.netloc

        try:
            context = ssl.create_default_context()
            with socket.create_connection((domain, 443)) as sock:
                with context.wrap_socket(sock, server_hostname=domain) as ssock:
                    cert = ssock.getpeercert()
                    expiry_date = cert['notAfter']
                    # Convert expiry date to UTC format
                    expiry_datetime = datetime.strptime(expiry_date, '%b %d %H:%M:%S %Y %Z')
                    result[domain] = expiry_datetime.strftime('%Y-%m-%d %H:%M:%S')
        except (ssl.SSLError, socket.error):
            # Ignore URLs with SSL errors or connection issues
            continue

    return result

[TESTS]
def test_1():
    assert task_func("Check these links: https://www.google.com, https://www.python.org") == {'www.google.com': '2023-06-15 12:00:00', 'www.python.org': '2023-07-20 12:00:00'}

def test_2():
    assert task_func("No URLs here") == {}

def test_3():
    assert task_func("Mixed links: http://example.com, https://www.example.com") == {'www.example.com': '2023-08-01 12:00:00'}

def test_4():
    assert task_func("Multiple links: https://firstsite.com, https://secondsite.com") == {'firstsite.com': '2023-08-02 12:00:00', 'secondsite.com': '2023-08-03 12:00:00'}

def test_5():
    assert task_func("Broken SSL: https://invalid-ssl-cert.com, https://validssl.com") == {'validssl.com': '2023-08-04 12:00:00'}

def test_6():
    assert task_func("https://subdomain.example.com") == {'subdomain.example.com': '2023-08-05 12:00:00'}

def test_7():
    assert task_func("https://nonexistentdomain12345.com") == {}
