import os
import hashlib
import base64

def task_func(password, PREFIX="ME", SALT_LENGTH=16):
    if SALT_LENGTH < 0:
        raise ValueError("SALT_LENGTH must be non-negative")
    salt = os.urandom(SALT_LENGTH)
    combined = PREFIX.encode() + password.encode() + salt
    hash_object = hashlib.sha256(combined)
    hashed_password = base64.b64encode(hash_object.digest()).decode()
    return hashed_password

import unittest

class TestTaskFunc(unittest.TestCase):
    def test_1(self):
        self.assertIsInstance(task_func('password123'), str)

    def test_2(self):
        self.assertNotEqual(task_func('password123', 'ME', 16), task_func('password123', 'ME', 16))

    def test_3(self):
        self.assertEqual(task_func('password123', 'ME', 0), task_func('password123', 'ME', 0))

    def test_4(self):
        with self.assertRaises(ValueError) as context:
            task_func('password123', 'ME', -1)
        self.assertEqual(str(context.exception), "SALT_LENGTH must be non-negative")

