        self.assertTrue(task_func('password123', 'ME', 16).startswith('ME'))

    def test_6(self):
        self.assertEqual(len(task_func('password123', 'ME', 16)), 44)  # Base64 encoding of 32 bytes (SHA256) is 44 characters

    def test_7(self):
        self.assertNotEqual(task_func('password123', '', 16), task_func('password123', 'ME', 16))

