import requests

def task_func(user, API_URL='https://api.github.com/users/'):
    response = requests.get(f"{API_URL}{user}/repos")
    if response.status_code == 200:
        repos = response.json()
        sorted_repos = sorted(repos, key=lambda repo: repo['created_at'])
        return [repo['name'] for repo in sorted_repos]
    else:
        return []

[TESTS]
def test_1():
    assert isinstance(task_func('octocat'), list)

def test_2():
    repos = task_func('octocat')
    assert all(isinstance(repo, str) for repo in repos)

def test_3():
    repos = task_func('octocat')
    assert len(repos) > 0, "Expected at least one repository"

def test_4():
    repos = task_func('octocat')
    assert repos == sorted(repos), "Repositories should be sorted by creation date"

def test_5():
    assert task_func('nonexistentuser') == [], "Non-existent user should return an empty list"

def test_6():
    repos_octocat = task_func('octocat')
    repos_twitter = task_func('twitter')
    assert repos_octocat != repos_twitter, "Different users should have different repositories"

def test_7():
    repos = task_func('octocat')
    if len(repos) > 1:
        assert repos[0] != repos[1], "Repository names should be unique in the sorted list"

